  grade xpms.canon_text not null,
  description xpms.canon_text,
  specification xpms.canon_text,
  xyz xpms.xyz_tag not null,
  xyz_basis xpms.canon_text not null,
  tier_code xpms.canon_code not null references xpms.dim_tier(tier_code),
  lead_time_hours numeric,
  crew xpms.canon_text,
  unspsc xpms.canon_code,
  purchase_account xpms.canon_code references xpms.dim_gl_account(account_code),
  sales_account xpms.canon_code references xpms.dim_gl_account(account_code),
  default_cost_center xpms.canon_code not null references xpms.dim_cost_center_template(cost_center_id),
  price_evidence xpms.canon_text,
  source xpms.canon_text not null,
  mapping_confidence xpms.canon_text not null,
  lifecycle_state xpms.canon_text not null references xpms.dim_state(state),
  external_ref xpms.canon_text,
  source_row integer,
  primary key (element_id),
  check (left(element_id, 11) = urid || '-'),
  check (purchase_account is not null or sales_account is not null)
);
