comment on column xpms.elements.unit_basis is 'Unit basis.';
comment on column xpms.elements.grade is 'Experience grade of the element: Standard, Base, Elevated or Premium.';
comment on column xpms.elements.description is 'Description, sentence case.';
comment on column xpms.elements.specification is 'Specification.';
comment on column xpms.elements.xyz is 'Schema family tag.';
comment on column xpms.elements.xyz_basis is 'Basis of the XYZ tag, stored beside it.';
comment on column xpms.elements.tier_code is 'Tier of experience.';
