  min_grade_rate_minor bigint check (min_grade_rate_minor >= 0),
  max_grade_rate_minor bigint check (max_grade_rate_minor >= 0),
  per_diem_rate_minor bigint check (per_diem_rate_minor >= 0),
  currency_code xpms.currency_code not null,
  overtime_rule_id xpms.canon_code not null references xpms.overtime_rule(rule_id),
  flag boolean,
  notes xpms.canon_text,
  source_row integer,
  source_status xpms.canon_text,
  source_created_by xpms.canon_text,
  source_created_at timestamp,
  source_updated_at timestamp,
  primary key (rate_card_id),
  unique (role_code, worker_classification, pay_basis, arrangement),
  unique (source_row),
  foreign key (pay_basis, worker_classification) references xpms.pay_basis_classification (pay_basis, worker_classification),
  foreign key (arrangement, worker_classification) references xpms.arrangement_classification (arrangement, worker_classification),
  check (max_grade_rate_minor is null or min_grade_rate_minor is null or max_grade_rate_minor >= min_grade_rate_minor)
);
comment on table xpms.rate_card is 'Labor Rate Cards (decisions D12 to D14 and D16): only the card''s own facts. Title, department, GL account and multipliers are joined or derived.';
comment on column xpms.rate_card.rate_card_id is 'Rate card code LRC-nnn.';
comment on column xpms.rate_card.role_code is 'Role the card prices.';
comment on column xpms.rate_card.worker_classification is 'Classification of the engagement the card prices.';
comment on column xpms.rate_card.pay_basis is 'How pay is computed.';
comment on column xpms.rate_card.arrangement is 'Retainer or per engagement.';
comment on column xpms.rate_card.standard_rate_minor is 'Standard rate in minor units of currency_code; NULL is unpriced.';
comment on column xpms.rate_card.min_grade_rate_minor is 'Lowest grade rate in minor units of currency_code; NULL is unpriced.';
comment on column xpms.rate_card.max_grade_rate_minor is 'Highest grade rate in minor units of currency_code; NULL is unpriced.';
comment on column xpms.rate_card.per_diem_rate_minor is 'Per diem in minor units of currency_code; NULL is unpriced.';
comment on column xpms.rate_card.currency_code is 'ISO 4217 currency of the amounts; the Playbook states US dollars.';
comment on column xpms.rate_card.overtime_rule_id is 'Overtime rule the card follows.';
comment on column xpms.rate_card.flag is 'FLAG from the Playbook Labor Rate Cards sheet.';
comment on column xpms.rate_card.notes is 'NOTES from the Playbook Labor Rate Cards sheet.';
comment on column xpms.rate_card.source_row is 'Row of the Playbook sheet that mirrors this canon row; NULL when the Playbook has no such row.';
comment on column xpms.rate_card.source_status is 'STATUS as recorded on the Playbook row (for example Active).';
comment on column xpms.rate_card.source_created_by is 'CREATED BY as recorded on the Playbook row.';
comment on column xpms.rate_card.source_created_at is 'CREATED AT as recorded on the Playbook row: a wall-clock time; the Playbook records no time zone.';
comment on column xpms.rate_card.source_updated_at is 'UPDATED AT as recorded on the Playbook row: a wall-clock time; the Playbook records no time zone.';
create index rate_card_overtime_rule_id_idx on xpms.rate_card (overtime_rule_id);
create index rate_card_pay_basis_worker_classification_idx on xpms.rate_card (pay_basis, worker_classification);
create index rate_card_arrangement_worker_classification_idx on xpms.rate_card (arrangement, worker_classification);

create table xpms.emergency_code (
  code xpms.canon_code not null check (code ~ '^CODE_[A-Z]+$'),
  label xpms.canon_text not null,
  emergency xpms.canon_text not null,
  swatch xpms.canon_code not null check (swatch ~ '^ecode-[a-z]+$'),
  sort_order integer not null,
  primary key (code),
  unique (label),
  unique (swatch),
  unique (sort_order)
);
comment on table xpms.emergency_code is 'Emergency codes, global: no organization, project or jurisdiction (decision D15). Numeric sort order.';
comment on column xpms.emergency_code.code is 'Code token, such as CODE_RED.';
comment on column xpms.emergency_code.label is 'Code word, such as Code Red.';
comment on column xpms.emergency_code.emergency is 'The emergency the code announces.';
comment on column xpms.emergency_code.swatch is 'Design token of the swatch (ecode-*).';
comment on column xpms.emergency_code.sort_order is 'Order of first appearance in the Playbook.';

create table xpms.operational_domain (
  domain xpms.canon_text not null,
  sort_order integer not null,
  primary key (domain),
  unique (sort_order)
);
comment on table xpms.operational_domain is 'Operational domains an emergency protocol is written for.';
comment on column xpms.operational_domain.domain is 'Domain name.';
comment on column xpms.operational_domain.sort_order is 'Order of first appearance in the Playbook.';

create table xpms.emergency_protocol (
  record_key xpms.canon_code not null check (record_key ~ '^EMG-[0-9]{3}$'),
  code xpms.canon_code not null references xpms.emergency_code(code),
  domain xpms.canon_text not null references xpms.operational_domain(domain),
  department xpms.canon_text,
  category xpms.canon_text,
  sub_category xpms.canon_text,
  flag boolean,
  notes xpms.canon_text,
  source_row integer,
  source_status xpms.canon_text,
  source_created_by xpms.canon_text,
  source_created_at timestamp,
  source_updated_at timestamp,
  primary key (record_key),
  unique (code, domain),
  unique (source_row)
);
comment on table xpms.emergency_protocol is 'The protocol for one code in one operational domain. Global; agencies are resolved per jurisdiction.';
comment on column xpms.emergency_protocol.record_key is 'Protocol key EMG-nnn.';
comment on column xpms.emergency_protocol.code is 'Emergency code.';
comment on column xpms.emergency_protocol.domain is 'Operational domain.';
comment on column xpms.emergency_protocol.department is 'DEPARTMENT from the Playbook Emergency Codes sheet.';
comment on column xpms.emergency_protocol.category is 'CATEGORY from the Playbook Emergency Codes sheet.';
comment on column xpms.emergency_protocol.sub_category is 'SUB CATEGORY from the Playbook Emergency Codes sheet.';
comment on column xpms.emergency_protocol.flag is 'FLAG from the Playbook Emergency Codes sheet.';
comment on column xpms.emergency_protocol.notes is 'NOTES from the Playbook Emergency Codes sheet.';
comment on column xpms.emergency_protocol.source_row is 'Row of the Playbook sheet that mirrors this canon row; NULL when the Playbook has no such row.';
comment on column xpms.emergency_protocol.source_status is 'STATUS as recorded on the Playbook row (for example Active).';
comment on column xpms.emergency_protocol.source_created_by is 'CREATED BY as recorded on the Playbook row.';
comment on column xpms.emergency_protocol.source_created_at is 'CREATED AT as recorded on the Playbook row: a wall-clock time; the Playbook records no time zone.';
comment on column xpms.emergency_protocol.source_updated_at is 'UPDATED AT as recorded on the Playbook row: a wall-clock time; the Playbook records no time zone.';
create index emergency_protocol_domain_idx on xpms.emergency_protocol (domain);

create table xpms.emergency_protocol_step (
  record_key xpms.canon_code not null references xpms.emergency_protocol(record_key) on delete cascade,
  step_no integer not null check (step_no >= 1),
  body xpms.canon_text not null,
  primary key (record_key, step_no)
);
comment on table xpms.emergency_protocol_step is 'Numbered protocol steps. Steps name services ({fire}, {ems}, {lawEnforcement}, {bombSquad}, {federal}), never an agency.';
comment on column xpms.emergency_protocol_step.record_key is 'Protocol.';
comment on column xpms.emergency_protocol_step.step_no is 'Step number.';
comment on column xpms.emergency_protocol_step.body is 'Step text, sentence case.';

create table xpms.version (
  version_code xpms.canon_code not null,
  generation integer not null check (generation > 0),
  bible_generated_at timestamp not null,
  bible_sha256 xpms.canon_code not null,
  item_catalog_sha256 xpms.canon_code not null,
  gl_chart_sha256 xpms.canon_code not null,
  playbook_sha256 xpms.canon_code not null,
  primary key (version_code)
);
comment on table xpms.version is 'Canon version and generation, with the hashes of the files the seed was generated from.';
comment on column xpms.version.version_code is 'Canon version, such as 4.0.';
comment on column xpms.version.generation is 'Import generation; increases when a canon change ships.';
comment on column xpms.version.bible_generated_at is 'generated_at stated in the Bible _generated tab.';
comment on column xpms.version.bible_sha256 is 'SHA-256 of the Bible workbook.';
comment on column xpms.version.item_catalog_sha256 is 'SHA-256 of the Item Catalog CSV.';
comment on column xpms.version.gl_chart_sha256 is 'SHA-256 of the GL chart CSV.';
comment on column xpms.version.playbook_sha256 is 'SHA-256 of the Production Playbook workbook.';

create table xpms.ratification (
  subject xpms.canon_text not null,
  ratifier xpms.canon_text not null,
  ratified_at timestamptz not null,
  note xpms.canon_text,
  primary key (subject)
);
comment on table xpms.ratification is 'Ratification records. The 4.0 grammar is proposed until a named ratifier is recorded here (Section 3.13).';
comment on column xpms.ratification.subject is 'What is ratified, such as the 4.0 grammar.';
comment on column xpms.ratification.ratifier is 'Named human ratifier.';
comment on column xpms.ratification.ratified_at is 'When the ratification was recorded.';
comment on column xpms.ratification.note is 'Ratification note.';

create table xpms.supersession (
  domain xpms.canon_code not null,
  code xpms.canon_code not null,
  successor_code xpms.canon_code not null,
  label xpms.canon_text not null,
  reason xpms.canon_text not null,
  primary key (domain, code),
  check (code <> successor_code)
);
comment on table xpms.supersession is 'Superseded codes and their successors. Supersession is data, so reverting is a data change; the graph stays acyclic.';
comment on column xpms.supersession.domain is 'Code domain, such as phase.';
comment on column xpms.supersession.code is 'Superseded code; historical references keep resolving.';
comment on column xpms.supersession.successor_code is 'Code that supersedes it.';
comment on column xpms.supersession.label is 'Label the superseded code carried.';
comment on column xpms.supersession.reason is 'Why the code was superseded.';

create table xpms.field_provenance (
  element_id xpms.canon_code not null references xpms.elements(element_id),
  field_name xpms.canon_code not null,
  provenance xpms.canon_code not null references xpms.dim_provenance(provenance),
  recorded_at timestamp not null,
  primary key (element_id, field_name)
);
comment on table xpms.field_provenance is 'Provenance of every populated canon field of an element (Section 3.8). A lower rank never overwrites a field written by a higher rank.';
comment on column xpms.field_provenance.element_id is 'Element whose field was written.';
comment on column xpms.field_provenance.field_name is 'Column of xpms.elements that was written.';
comment on column xpms.field_provenance.provenance is 'Provenance of the write.';
comment on column xpms.field_provenance.recorded_at is 'When the write was recorded (the Bible generation time for imported values).';
create index field_provenance_provenance_idx on xpms.field_provenance (provenance);

create table xpms.intake (
  source_file xpms.canon_text not null,
  source_sheet xpms.canon_text not null,
  source_row integer not null,
  source_column xpms.canon_text not null,
  target_table xpms.canon_code not null,
  target_key xpms.canon_text not null,
  target_column xpms.canon_code not null,
  proposed_value xpms.canon_text,
  canon_value xpms.canon_text,
  reason xpms.canon_text not null,
  intake_state xpms.canon_text not null references xpms.dim_state(state),
  primary key (source_file, source_sheet, source_row, source_column)
);
comment on table xpms.intake is 'Staging for proposed canon additions and changes awaiting an owner decision. Neither source silently wins: a value that disagrees with canon or cannot be resolved waits here.';
comment on column xpms.intake.source_file is 'Canon input file the value comes from.';
comment on column xpms.intake.source_sheet is 'Sheet, tab or CSV the value comes from.';
comment on column xpms.intake.source_row is 'Source row number.';
comment on column xpms.intake.source_column is 'Source column header.';
comment on column xpms.intake.target_table is 'xpms table the value would change.';
comment on column xpms.intake.target_key is 'Natural key of the target row.';
comment on column xpms.intake.target_column is 'Column the value would change.';
comment on column xpms.intake.proposed_value is 'Value as the source states it; NULL when the source is blank.';
comment on column xpms.intake.canon_value is 'Value canon currently holds; NULL when canon is silent.';
comment on column xpms.intake.reason is 'Why the value is held for a decision.';
comment on column xpms.intake.intake_state is 'State of the proposal; Proposed until the owner decides.';
create index intake_intake_state_idx on xpms.intake (intake_state);
